var n=`0489-muhammara`;var a=`world-0489`;var t=`SY`;var r=`western-asia`;var s=4;var l=32;var o={en:`Muhammara`,ua:`Мухаммара`};var g={en:`A traditional dish from Syria, centered on red bell pepper, walnut, breadcrumbs, garlic. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: червоний солодкий перець, волоський горіх, панірувальні сухарі, часник. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Cut the vegetables evenly and roast at 200°C for about 20 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 20 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:20,i:[[`red-bell-pepper`,700,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`walnut`,160,`g`],[`breadcrumbs`,80,`g`],[`pomegranate-molasses`,75,`ml`],[`garlic`,3,`clove`],[`ground-cumin`,3,`g`],[`hot-paprika`,4,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`]]}];var d={slug:n,id:a,country:`SY`,region:r,servings:4,minutes:32,title:o,text:g,steps:m};export{t as country,d as default,a as id,l as minutes,r as region,s as servings,n as slug,m as steps,g as text,o as title};